/runtime/node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace } from './src/workspace.js';

const event = detail => Object.assign(new Event('progress'), { detail });
const target = new EventTarget();
let starts = 0;
let resolveLater;
const pending = new Promise(resolve => { resolveLater = resolve; });
const frames = [];
const shown = [];
const file = {
  id: 'warm-file',
  progressFeed: {
    target,
    start() {
      starts++;
      if (starts === 1) target.dispatchEvent(event('cached'));
    },
    decode(packet) {
      if (packet === 'late') return pending;
      return { seq: packet, loaded: packet === 'cached' ? 1 : 2 };
    },
  },
};
const app = createTransferWorkspace({
  transport() {}, onCancel() {}, record() {}, showQueued() {},
  recordProgress: item => frames.push(item),
  showProgress: item => shown.push(item),
});
app.select(file);
assert.deepEqual(frames.map(x => x.frame.seq), ['cached']);
assert.deepEqual(shown.map(x => x.frame.seq), ['cached']);
target.dispatchEvent(event('stream'));
assert.deepEqual(frames.map(x => x.frame.seq), ['cached', 'stream']);
assert.deepEqual(shown.map(x => x.frame.seq), ['cached', 'stream']);
target.dispatchEvent(event('late'));
app.hide();
resolveLater({ seq: 'late', loaded: 3 });
await Promise.resolve();
assert.deepEqual(frames.map(x => x.frame.seq), ['cached', 'stream', 'late']);
assert.deepEqual(shown.map(x => x.frame.seq), ['cached', 'stream']);
app.select(file);
assert.equal(starts, 2);
assert.deepEqual(frames.map(x => x.frame.seq), ['cached', 'stream', 'late', 'cached']);
console.log('progress lifecycle checks passed');
EOF
